#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
# Resolve the Python interpreter used by synaptory hooks.
#
# v2.1.16+ ships plaintext .py source — no .pyc compilation, so no
# magic-number drift between build-time and runtime Python versions. The
# only requirement is Python 3.9+ on the user's system.
#
# Resolution order (first working match wins):
#   1. SYNAPTORY_PYTHON env var (operator override — still version-checked)
#   2. python3 / python3.9 … python3.15 on PATH
#   3. Common install locations: Homebrew, pyenv shims, pyenv versions, asdf

_synaptory_find_python() {
  local name="$1" path candidate
  path="$(command -v "$name" 2>/dev/null || true)"
  if [ -n "$path" ] && [ -x "$path" ]; then printf '%s' "$path"; return 0; fi
  for candidate in \
    "/opt/homebrew/bin/$name" \
    "/usr/local/bin/$name" \
    "$HOME/.pyenv/shims/$name" \
    "$HOME/.asdf/shims/$name"; do
    [ -x "$candidate" ] && { printf '%s' "$candidate"; return 0; }
  done
  for candidate in "$HOME/.pyenv/versions"/*/bin/"$name"; do
    [ -x "$candidate" ] && { printf '%s' "$candidate"; return 0; }
  done
  return 1
}

_synaptory_check_version() {
  local py="$1"
  [ -x "$py" ] || return 1
  "$py" -c "import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)" 2>/dev/null
}

if [ -n "${SYNAPTORY_PYTHON:-}" ]; then
  if ! _synaptory_check_version "${SYNAPTORY_PYTHON}"; then
    _ver=$("${SYNAPTORY_PYTHON}" --version 2>&1 || echo unknown)
    echo "synaptory: SYNAPTORY_PYTHON=${SYNAPTORY_PYTHON} (${_ver}) is older than Python 3.9. Set it to a newer interpreter." >&2
    unset SYNAPTORY_PYTHON _ver
  else
    export SYNAPTORY_PYTHON
  fi
fi

if [ -z "${SYNAPTORY_PYTHON:-}" ]; then
  for _name in python3 python3.13 python3.12 python3.11 python3.10 python3.9 python3.14 python3.15 python; do
    _synaptory_resolved="$(_synaptory_find_python "$_name")" || continue
    if _synaptory_check_version "$_synaptory_resolved"; then
      SYNAPTORY_PYTHON="$_synaptory_resolved"
      export SYNAPTORY_PYTHON
      break
    fi
  done
  unset _name _synaptory_resolved
fi

unset -f _synaptory_find_python _synaptory_check_version
